import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
class NotificationHistoryService { final FirebaseFirestore db; final FirebaseAuth auth; NotificationHistoryService({FirebaseFirestore? firestore,FirebaseAuth? firebaseAuth}):db=firestore??FirebaseFirestore.instance,auth=firebaseAuth??FirebaseAuth.instance; CollectionReference<Map<String,dynamic>> get ref=>db.collection('users').doc(auth.currentUser!.uid).collection('notificationHistory'); Future<void> add(String type,String title,String body,{String? route,Map<String,dynamic>? data})=>ref.add({'type':type,'title':title,'body':body,'route':route,'data':data??{},'read':false,'createdAt':FieldValue.serverTimestamp()}); Future<void> markRead(String id)=>ref.doc(id).update({'read':true,'readAt':FieldValue.serverTimestamp()}); }